export function HamburgerMenu({
  label = "{{label}}",
  accent = "{{accent}}",
  open = {{open}},
  position = "{{position}}",
}) {
  return (
    <details open={open} style={{ width: "fit-content", fontFamily: "system-ui, sans-serif", fontSize: 14, fontWeight: 500, textAlign: position === "right" ? "right" : "left" }}>
      <summary aria-label={label} style={{ listStyle: "none", cursor: "pointer", display: "flex", flexDirection: "column", gap: 4, padding: 10, borderRadius: 8, width: 20 }}>
        <span style={{ display: "block", height: 2, background: "#241430", borderRadius: 2 }} />
        <span style={{ display: "block", height: 2, background: "#241430", borderRadius: 2 }} />
        <span style={{ display: "block", height: 2, background: "#241430", borderRadius: 2 }} />
      </summary>
      <nav aria-label="Mobile" style={{ marginTop: 6, marginLeft: position === "right" ? "auto" : 0, width: 180, background: "#fff", border: "1px solid rgba(36,20,48,.12)", borderRadius: 10, boxShadow: "0 8px 24px rgba(36,20,48,.14)", padding: 6, display: "flex", flexDirection: "column", gap: 2 }}>
        <a href="#" aria-current="page" style={{ padding: "8px 10px", borderRadius: 8, textDecoration: "none", color: accent, fontWeight: 600 }}>Home</a>
        <a href="#" style={{ padding: "8px 10px", borderRadius: 8, textDecoration: "none", color: "#241430", opacity: .7 }}>Shop</a>
        <a href="#" style={{ padding: "8px 10px", borderRadius: 8, textDecoration: "none", color: "#241430", opacity: .7 }}>About</a>
        <a href="#" style={{ padding: "8px 10px", borderRadius: 8, textDecoration: "none", color: "#241430", opacity: .7 }}>Contact</a>
      </nav>
    </details>
  );
}
